// F-OBS-001 admin read APIs. SELECT-only: no hot-path, quota, billing,
// auth, or trust-chain mutation is allowed here.
func (q *Queries) ListUsageRecords(ctx context.Context, arg ListUsageRecordsParams) ([]ListUsageRecordsRow, error) {
	rows, err := q.db.Query(ctx, listUsageRecords,
		arg.TenantID,
		arg.FromTs,
		arg.ToTs,
		arg.Provider,
		arg.PoolID,
		arg.APIKeyID,
		arg.ProviderAccountID,
		arg.Model,
		arg.PendingReconciliationOnly,
		arg.HasCursor,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUsageRecordsRow
	for rows.Next() {
		var i ListUsageRecordsRow
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.ClaimID,
			&i.APIKeyID,
			&i.UserID,
			&i.ProviderAccountID,
			&i.AttemptSeq,
			&i.TokensInput,
			&i.TokensOutput,
			&i.CacheCreationTokens,
			&i.CacheReadTokens,
			&i.ActualCost,
			&i.EndClass,
			&i.UsageSource,
			&i.PendingReconciliation,
			&i.StreamState,
			&i.DeliveredTokenCount,
			&i.StreamTerminatedReason,
			&i.RequestedAt,
			&i.CreatedAt,
			&i.RequestedModel,
			&i.UpstreamModel,
			&i.Stream,
			&i.SettlementSource,
			&i.Provider,
			&i.PoolID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
